(1717949, 232798, 27133, '<td valign="top">Wow...this is wicked.  I hope you didn''t get hurt in the process.</td>', 'Wow...this is wicked.  I hope you didn''t get hurt in the process.', '2005-09-18 06:59:26.000000', NULL, 1),
(1717950, 232293, 27133, '<td valign="top">Hehehehe...well put together...!  I like the strong tones.</td>', 'Hehehehe...well put together...!  I like the strong tones.', '2005-09-18 07:00:02.000000', NULL, 1),
(1717951, 232577, 27133, '<td valign="top">Hahahahaha....good work.  Well thought out image.</td>', 'Hahahahaha....good work.  Well thought out image.', '2005-09-18 07:00:37.000000', NULL, 1),
(1717952, 232316, 27133, '<td valign="top">Good work....I like the green hues to add mood to this capture.</td>', 'Good work....I like the green hues to add mood to this capture.', '2005-09-18 07:01:07.000000', NULL, 1),
(1717953, 232650, 27133, '<td valign="top">Oh poor squashed tomato....what a shame.  But very unique idea and well thought out.</td>', 'Oh poor squashed tomato....what a shame.  But very unique idea and well thought out.', '2005-09-18 07:02:14.000000', NULL, 1),
(1717954, 232642, 36628, '<td valign="top">I like the treatment of the flag, but I wish the background stars were a little bit more clear.</td>', 'I like the treatment of the flag, but I wish the background stars were a little bit more clear.', '2005-09-18 07:02:17.000000', NULL, 1),
(1717957, 232090, 36628, '<td valign="top">I''m not sure this works quite so well within the challenge..it looks more like kisses to me. To make the shot a little more vibrant, you might try adding a little more contrast and brightining it.</td>', 'I''m not sure this works quite so well within the challenge..it looks more like kisses to me. To make the shot a little more vibrant, you might try adding a little more contrast and brightining it.', '2005-09-18 07:04:09.000000', NULL, 1),
(1717958, 232642, 27133, '<td valign="top">Good choice of angle.  I like the textured feel to this.</td>', 'Good choice of angle.  I like the textured feel to this.', '2005-09-18 07:04:56.000000', NULL, 1),
(1717960, 232315, 27133, '<td valign="top">Good clear details....nicely captured.  I really like the brown hues over the left against the striking colours on the right.</td>', 'Good clear details....nicely captured.  I really like the brown hues over the left against the striking colours on the right.', '2005-09-18 07:08:11.000000', NULL, 1),
(1717961, 232292, 30896, '<td valign="top">Oh no, the print is too small - how are we supposed to learn and improve here when stuff like this is being burnt in front of our eyes. provocation. <br/>the photo itself is well composed. i wander how difficult it is to capture flames in front of black background (shall have to try). may be the hand should be slightly more lit.</td>', 'Oh no, the print is too small - how are we supposed to learn and improve here when stuff like this is being burnt in front of our eyes. provocation. the photo itself is well composed. i wander how difficult it is to capture flames in front of black background (shall have to try). may be the hand should be slightly more lit.', '2005-09-18 07:09:06.000000', NULL, 1),
(1717963, 232671, 36628, '<td valign="top">It looks like theres a little bit of color-noise in here. I think you could greatly improve this shot by desaturating it all the way to get rid of the off-color pixels, and boosting the contrast to darken the backgroun and make the moon stand out.</td>', 'It looks like theres a little bit of color-noise in here. I think you could greatly improve this shot by desaturating it all the way to get rid of the off-color pixels, and boosting the contrast to darken the backgroun and make the moon stand out.', '2005-09-18 07:09:21.000000', NULL, 1),
(1717964, 232031, 3306, '<td valign="top">Simple and to the point. Well done.</td>', 'Simple and to the point. Well done.', '2005-09-18 07:09:41.000000', NULL, 1),
(1717965, 232549, 27133, '<td valign="top">Good moody feel....it leaves one with a suspicious feeling.  Good work.</td>', 'Good moody feel....it leaves one with a suspicious feeling.  Good work.', '2005-09-18 07:10:42.000000', NULL, 1),
(1717967, 232442, 36628, '<td valign="top">I like the composition and idea, but the colors are a little flat. You might try changing the curves or boosting the contrast a little bit to make the shot a little bit more vivid.</td>', 'I like the composition and idea, but the colors are a little flat. You might try changing the curves or boosting the contrast a little bit to make the shot a little bit more vivid.', '2005-09-18 07:12:29.000000', NULL, 1);
