(1721306, 232087, 37961, '<td valign="top">Not that amazing of a photo (meaning you see this in all colleges &amp; schools) but the angle you shot it at, the clarity, colors and title push it into a great photo in my opinion. 9.</td>', 'Not that amazing of a photo (meaning you see this in all colleges & schools) but the angle you shot it at, the clarity, colors and title push it into a great photo in my opinion. 9.', '2005-09-19 15:34:18.000000', NULL, 1),
(1721318, 232265, 37961, '<td valign="top">Sleazy undertones. Ick. But point well taken....nastay! Just goes to show you how important titles are. Otherwise this wouldn''t have had near the impact. However I think you did misquote it. It should be.''<br/> <br/> I did not have sexual intercourse with that woman''!</td>', 'Sleazy undertones. Ick. But point well taken....nastay! Just goes to show you how important titles are. Otherwise this wouldn''t have had near the impact. However I think you did misquote it. It should be.''  I did not have sexual intercourse with that woman''!', '2005-09-19 15:37:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1721321, 232646, 37961, '<td valign="top">Boy, somebodys mind is in the gutter! Hysterical!</td>', 'Boy, somebodys mind is in the gutter! Hysterical!', '2005-09-19 15:38:19.000000', NULL, 1),
(1721322, 232653, 37961, '<td valign="top">Wow, this really looks like the lettuce is beinb cornered. COOL. Light is great, colors too.</td>', 'Wow, this really looks like the lettuce is beinb cornered. COOL. Light is great, colors too.', '2005-09-19 15:39:02.000000', NULL, 1),
(1721418, 232374, 10263, '<td valign="top">The grainy effect with the flecks of color adds interest to this photo. Original.. nice.</td>', 'The grainy effect with the flecks of color adds interest to this photo. Original.. nice.', '2005-09-19 16:36:02.000000', NULL, 1),
(1721425, 232115, 10263, '<td valign="top">This would be good in perspective too :) I like it..</td>', 'This would be good in perspective too :) I like it..', '2005-09-19 16:38:56.000000', NULL, 1),
(1721440, 232772, 10263, '<td valign="top">This is funny. Not particularly an interesting photo but sure fits the challenge</td>', 'This is funny. Not particularly an interesting photo but sure fits the challenge', '2005-09-19 16:41:45.000000', NULL, 1),
(1721454, 232222, 10263, '<td valign="top">The idea is good but the photo isn''t really interesting. It is too scattered. Maybe a darker room with just a little light like a flashlight beam on the top secret card would have worked better. Good luck</td>', 'The idea is good but the photo isn''t really interesting. It is too scattered. Maybe a darker room with just a little light like a flashlight beam on the top secret card would have worked better. Good luck', '2005-09-19 16:45:03.000000', NULL, 1),
(1721493, 232750, 10263, '<td valign="top">ok I''m trying to comment on photos I give the highest and lowest scores to and I''ll admit this scored pretty low. First I don''t really get the connection to the challenge topic. And there is nothing that grabs my attention. The little tree tops distract rather than add to the  composition I think. There is a lot of resizing residue (the wavy lines on the wires). You did a good job on the pole placement and I like how the sky blends with the lighter to darker shadeing. Keep trying. Its amazing how fast you can learn here :)</td>', 'ok I''m trying to comment on photos I give the highest and lowest scores to and I''ll admit this scored pretty low. First I don''t really get the connection to the challenge topic. And there is nothing that grabs my attention. The little tree tops distract rather than add to the  composition I think. There is a lot of resizing residue (the wavy lines on the wires). You did a good job on the pole placement and I like how the sky blends with the lighter to darker shadeing. Keep trying. Its amazing how fast you can learn here :)', '2005-09-19 16:59:38.000000', NULL, 1),
(1721509, 232697, 10263, '<td valign="top">I see what you are going for here. Clever idea. The colors are a bit washed out giving the photo a flat look. Maybe putting the subject less centered would have helped too. Good luck. :)</td>', 'I see what you are going for here. Clever idea. The colors are a bit washed out giving the photo a flat look. Maybe putting the subject less centered would have helped too. Good luck. :)', '2005-09-19 17:05:19.000000', NULL, 1),
(1721589, 232640, 40355, '<td valign="top">This is sooo cool!  Great shot, love the high contrast and composition.  9</td>', 'This is sooo cool!  Great shot, love the high contrast and composition.  9', '2005-09-19 17:30:05.000000', NULL, 1),
(1721592, 232226, 40355, '<td valign="top">I KNEW he wasn''t dead!  Long live the King!  8</td>', 'I KNEW he wasn''t dead!  Long live the King!  8', '2005-09-19 17:31:24.000000', NULL, 1),
(1721595, 232703, 40355, '<td valign="top">Neat shot, but the edges of the man seem a bit too obvious...maybe over sharpened?  7</td>', 'Neat shot, but the edges of the man seem a bit too obvious...maybe over sharpened?  7', '2005-09-19 17:34:16.000000', NULL, 1),
(1721596, 232293, 40355, '<td valign="top">This is well done!  Like the use of B&amp;W, sharp and well composed.  Good shot!</td>', 'This is well done!  Like the use of B&W, sharp and well composed.  Good shot!', '2005-09-19 17:35:12.000000', NULL, 1),
(1721602, 232030, 40355, '<td valign="top">Geeze...kids/younger siblings get the raw deal when it comes to helping us with out photos...lol  I like it, it''s funny!</td>', 'Geeze...kids/younger siblings get the raw deal when it comes to helping us with out photos...lol  I like it, it''s funny!', '2005-09-19 17:36:49.000000', NULL, 1),
